"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["75547"],{77750(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>h});var n=JSON.parse('{"id":"nhcx/v1/concepts/nhcx-way-of-claim-settlement","title":"NHCX way of claim settlement","description":"How the ten steps become structured exchanges: the request and callback pattern, and the six exchanges that carry a claim.","source":"@site/docs/nhcx/v1/concepts/nhcx-way-of-claim-settlement.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1/concepts/nhcx-way-of-claim-settlement","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/nhcx-way-of-claim-settlement","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1788936730000,"sidebarPosition":4,"frontMatter":{"title":"NHCX way of claim settlement","sidebar_label":"The NHCX way","description":"How the ten steps become structured exchanges: the request and callback pattern, and the six exchanges that carry a claim.","verification":"unverified","source":"NHCX sandbox portal, Technical Specifications and Open Protocol pages; NHCX Integration Handbook v1.0 (Aug 2026); NHCX FAQs v1.2 (Aug 2026)","sidebar_position":4},"sidebar":"nhcx-v1-overview","previous":{"title":"Claim settlement","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/claim-settlement"},"next":{"title":"JWE, status and errors","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/jwe-status-and-errors"}}'),s=t(62540),i=t(43023);let r={title:"NHCX way of claim settlement",sidebar_label:"The NHCX way",description:"How the ten steps become structured exchanges: the request and callback pattern, and the six exchanges that carry a claim.",verification:"unverified",source:"NHCX sandbox portal, Technical Specifications and Open Protocol pages; NHCX Integration Handbook v1.0 (Aug 2026); NHCX FAQs v1.2 (Aug 2026)",sidebar_position:4},o="NHCX way of claim settlement",h={},c=[{value:"In short",id:"in-short",level:2},{value:"From portals to an exchange",id:"from-portals-to-an-exchange",level:2},{value:"What travels over the exchange",id:"what-travels-over-the-exchange",level:2},{value:"The request and callback pattern",id:"the-request-and-callback-pattern",level:2},{value:"What every exchange needs",id:"what-every-exchange-needs",level:2},{value:"The exchanges in a claim",id:"the-exchanges-in-a-claim",level:2},{value:"Coverage eligibility",id:"coverage-eligibility",level:3},{value:"Insurance plan",id:"insurance-plan",level:3},{value:"Preauthorisation",id:"preauthorisation",level:3},{value:"Query",id:"query",level:3},{value:"Claim",id:"claim",level:3},{value:"Payment",id:"payment",level:3},{value:"Off the main path",id:"off-the-main-path",level:3},{value:"What a participant must build",id:"what-a-participant-must-build",level:2},{value:"Where the detail lives",id:"where-the-detail-lives",level:2}];function l(e){let a={code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"nhcx-way-of-claim-settlement",children:"NHCX way of claim settlement"})}),"\n",(0,s.jsx)(a.p,{children:"The ten steps of claim settlement do not change under NHCX. The same parties make the same decisions about the same case. What changes is the medium: instead of email threads and some 30-odd insurer portals, each step becomes a structured exchange over a single gateway, carrying FHIR resources rather than PDFs and scans."}),"\n",(0,s.jsx)(a.h2,{id:"in-short",children:"In short"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsx)(a.li,{children:"The ten steps do not change. The medium does: structured exchanges over one gateway, carrying FHIR rather than PDFs."}),"\n",(0,s.jsxs)(a.li,{children:["Every substantive use case is an asynchronous pair: an action endpoint, then a matching ",(0,s.jsx)(a.code,{children:"on_"})," callback."]}),"\n",(0,s.jsx)(a.li,{children:'There are two acknowledgements. The first says only "accepted and passed on".'}),"\n",(0,s.jsx)(a.li,{children:"Six exchanges carry the claim; Task, search, ABHA linking and predetermination sit off the main path."}),"\n",(0,s.jsx)(a.li,{children:"Both sides host endpoints, so no participant is purely an API caller."}),"\n"]}),"\n",(0,s.jsx)(a.h2,{id:"from-portals-to-an-exchange",children:"From portals to an exchange"}),"\n",(0,s.jsx)(a.p,{children:"Today a hospital integrates separately with every insurer. Each new payer means another portal, another login, another upload convention. The cost grows with the number of payers, which is why smaller hospitals often stay out of cashless arrangements altogether."}),"\n",(0,s.jsx)(a.p,{children:"On NHCX, a Provider integrates once and a Payer integrates once, each with the exchange. Every Provider can then reach every Payer, and the reverse, without either side building anything specific to the other. As on a securities exchange, participants connect to the platform rather than to each other."}),"\n",(0,s.jsx)(a.h2,{id:"what-travels-over-the-exchange",children:"What travels over the exchange"}),"\n",(0,s.jsx)(a.p,{children:"Every exchange carries a FHIR bundle, and this is what makes the rest possible."}),"\n",(0,s.jsx)(a.p,{children:"A discharge summary sent as a PDF can be stored and read by a person, but nothing downstream can act on its contents. The same information as FHIR resources lets the payer's system read the diagnosis, the procedure codes, the line items and the amounts as data. That is the precondition for auto-adjudication and for the parameter-by-parameter reporting described in the introduction. Standard terminologies are used alongside FHIR so that a code written by the Provider means the same thing when read by the Payer. SNOMED CT for clinical concepts, ICD for diagnoses, LOINC for laboratory observations, and the value sets NRCeS publishes for claim-specific codes such as packages, benefit categories and supporting-information types."}),"\n",(0,s.jsx)(a.h2,{id:"the-request-and-callback-pattern",children:"The request and callback pattern"}),"\n",(0,s.jsx)(a.p,{children:"Claim decisions take time. A preauthorisation may sit with a medical officer for hours, an adjudication for days. NHCX therefore models every substantive use case as an asynchronous pair:"}),"\n",(0,s.jsxs)(a.ol,{children:["\n",(0,s.jsxs)(a.li,{children:["The initiator calls an action endpoint, for example ",(0,s.jsx)(a.code,{children:"/v1/preauth/submit"}),". The exchange validates the request, acknowledges it, and routes it onward."]}),"\n",(0,s.jsxs)(a.li,{children:["The responder does its work, then calls the matching ",(0,s.jsx)(a.code,{children:"on_"})," endpoint, ",(0,s.jsx)(a.code,{children:"/v1/preauth/on_submit"}),", to deliver the outcome back through the exchange."]}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:'There are two acknowledgements, not one, and the difference matters. When the initiator sends a request, the exchange answers straight away with a receipt that says only "accepted and passed on". That receipt is not the decision. The decision arrives later, on the callback, when the responder has actually done the work. The exchange never answers a claim question on the spot; anyone waiting for a synchronous yes or no will wait forever.'}),"\n",(0,s.jsx)(a.mermaid,{value:"sequenceDiagram\n  box rgb(220,239,227) Provider side\n    participant P as Provider\n  end\n  box rgb(227,240,240) Exchange\n    participant X as NHCX\n  end\n  box rgb(220,232,245) Payer side\n    participant Y as Payer\n  end\n  P->>X: preauth/submit\n  X--\x3e>P: 202 receipt: accepted, not decided\n  X->>Y: forwards the request\n  Y--\x3e>X: 202 receipt\n  Note over Y: hours or days pass\n  Y->>X: preauth/on_submit with the decision\n  X--\x3e>Y: 202 receipt\n  X->>P: delivers to the provider's callback\n  P--\x3e>X: 202 receipt"}),"\n",(0,s.jsx)(a.p,{children:"Two consequences follow. Participation is never purely a matter of calling APIs, because in one half of every exchange each side is the responder and must host endpoints. And every request has an acknowledgement and a matching response, which is what makes the process auditable."}),"\n",(0,s.jsx)(a.h2,{id:"what-every-exchange-needs",children:"What every exchange needs"}),"\n",(0,s.jsx)(a.p,{children:"Four things are common to all traffic, before any claim-specific call is made."}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"Identity."})," Participants are registered on the exchange and addressed by participant ID. The registry can be queried by role to find them."]}),"\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"Authentication."})," Calls carry a token obtained from the ABDM gateway's sessions endpoint, with the same login a hospital already has from Milestone 1."]}),"\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"Confidentiality."})," Payloads are encrypted for the receiver, using the receiver's public key, fetched from the exchange against their participant ID."]}),"\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"Traceability."})," A status call returns the state of any request already triggered, so neither side has to infer what happened from silence."]}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"Both Providers and Payers implement these. They are the shared use cases, and the next chapter takes each in turn: how a participant is registered and found, how a session is obtained, and how a receiver's key is fetched and used."}),"\n",(0,s.jsx)(a.h2,{id:"the-exchanges-in-a-claim",children:"The exchanges in a claim"}),"\n",(0,s.jsx)(a.p,{children:"Each stage of the journey becomes an exchange on the network. Six carry the claim, and a handful sit off the main path."}),"\n",(0,s.jsx)(a.mermaid,{value:'flowchart TD\n  classDef provider fill:#DCEFE3,stroke:#2E7D4F,color:#1B2431\n  classDef payer fill:#DCE8F5,stroke:#2B5C9E,color:#1B2431\n  classDef exchange fill:#E3F0F0,stroke:#0F6E70,color:#1B2431\n  classDef other fill:#EEF1F4,stroke:#7A8797,color:#1B2431\n  A[Patient arrives] --\x3e B[Coverage eligibility]\n  B --\x3e C[Insurance plan]\n  C --\x3e D[Preauthorisation]\n  D --\x3e Q1{Payer answer}\n  Q1 -- query --\x3e D3[Answer the query] --\x3e Q1\n  Q1 -- approved --\x3e E[Treatment]\n  E --\x3e E2{Case needs more?}\n  E2 -- yes --\x3e F[Enhancement] --\x3e Q1\n  E2 -- no --\x3e G[Discharge and claim]\n  G --\x3e Q2{Payer answer}\n  Q2 -- query --\x3e G3[Answer the query] --\x3e Q2\n  Q2 -- decided --\x3e H[Adjudication]\n  H --\x3e I[Payment notice]\n  I --\x3e J[Acknowledgement]\n  H -. rejected or paid short .-> K["Task: reprocess or shortfall"]\n  D -. withdraw .-> L["Task: cancel"]\n  class A,B,C,D,D3,E,E2,F,G,G3,J,K,L provider\n  class Q1,Q2,H,I payer'}),"\n",(0,s.jsx)(a.h3,{id:"coverage-eligibility",children:"Coverage eligibility"}),"\n",(0,s.jsx)(a.p,{children:"A patient arrives and presents a policy, or is found against one by mobile number or ABHA. Both sides now need the same assurance from opposite directions. The hospital needs to know the policy is live and covers the ailment. The insurer needs to know a genuine beneficiary has turned up at a hospital it has a tie-up with."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.em,{children:"Policy verification by the hospital"})," and ",(0,s.jsx)(a.em,{children:"beneficiary and tie-up verification by the insurer"})," are therefore not two conversations on the network. They are one exchange. The Provider asks whether coverage is in force, valid at a date, and what benefits and plan details attach to it. The Payer answers through the callback. What used to take a phone call and a portal login is settled in one round trip. The answer is a machine-readable set of limits the hospital's system can act on rather than a screenshot someone reads."]}),"\n",(0,s.jsx)(a.p,{children:"This exchange is also the gate on registration. A patient is registered for treatment only once coverage is confirmed, and repeat the check whenever an additional treatment is added, so the remaining limit is known before anything is submitted."}),"\n",(0,s.jsx)(a.h3,{id:"insurance-plan",children:"Insurance plan"}),"\n",(0,s.jsx)(a.p,{children:"Eligibility answers whether a patient is covered. The insurance plan answers what the policy itself contains: the covered services and their limits, the conditions and exclusions, the documents required, and the clinical guidelines that apply."}),"\n",(0,s.jsx)(a.p,{children:"It is a separate exchange because it changes on a different clock. Eligibility is asked per patient, per visit. The plan belongs to the policy and can be fetched once and kept, refreshed when the payer amends or renews it. Holding it locally is what lets a hospital system populate a form with the right benefits and check a treatment against the policy before anyone submits anything."}),"\n",(0,s.jsx)(a.h3,{id:"preauthorisation",children:"Preauthorisation"}),"\n",(0,s.jsxs)(a.p,{children:["With coverage established, the hospital sets out what it intends to do: the line of treatment, the procedures, the expected length of stay. ",(0,s.jsx)(a.em,{children:"Treatment plan intimation"})," and ",(0,s.jsx)(a.em,{children:"preauthorisation"})," are the two halves of one exchange. The Provider submits the request, the Payer adjudicates it and returns the decision through the callback, and the patient is admitted on that decision."]}),"\n",(0,s.jsxs)(a.p,{children:["The same exchange carries the whole preauthorisation cycle, not just the first request. An ",(0,s.jsx)(a.em,{children:"enhancement"}),", where the case needs an additional procedure or a longer stay, is raised against the cycle already open. A resubmission revises a request that was rejected or approved for the wrong amount. A cancellation withdraws it. All of these reuse the same bundle, which is why the exchange is best thought of as a conversation about one authorisation rather than a single call."]}),"\n",(0,s.jsx)(a.h3,{id:"query",children:"Query"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.em,{children:"Query"})," is the one stage where the direction reverses. Everywhere else the Provider initiates and the Payer responds. Here the Payer asks for something it needs before it can decide, and the Provider answers."]}),"\n",(0,s.jsx)(a.p,{children:"That reversal is why the same query endpoints appear on both sides of the NHCX Use Cases chapter: once as the Payer raising the request, once as the Provider answering it. A query is also not a rejection. The case stays open, and answering it continues the original submission rather than starting a new one."}),"\n",(0,s.jsx)(a.h3,{id:"claim",children:"Claim"}),"\n",(0,s.jsxs)(a.p,{children:["At discharge, everything that was previously printed, scanned and emailed becomes the claim. ",(0,s.jsx)(a.em,{children:"Discharge and document submission"})," is a single submission carrying the consultation notes, diagnostic reports, medication record, discharge summary and bills as FHIR resources. That is what lets the Payer read the values rather than look at pictures of them."]}),"\n",(0,s.jsx)(a.p,{children:"On the general network there is also a step before the claim. A hospital can send a provisional discharge submission while the patient is still on the ward, so the payer can check the treatment against the preauthorisation and raise anything it needs before the patient leaves. Under PMJAY this step does not exist and discharge is folded into the claim."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.em,{children:"Adjudication"})," is not a separate exchange. It is the Payer's response to the claim already submitted, carrying whether the amount is granted, denied or partially granted, and the reasons. So the claim and its decision are two halves of one exchange, in the same way as the preauthorisation and its decision."]}),"\n",(0,s.jsx)(a.h3,{id:"payment",children:"Payment"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.em,{children:"Payment"})," arrives as a notice from the Payer carrying the bank reference details and the status of the transfer, which the Provider acknowledges. Reconciliation gives the breakup for the case."]}),"\n",(0,s.jsx)(a.p,{children:"The acknowledgement closes the claim on both books at the same moment, which the current email-and-portal mechanism cannot do, so neither side has to chase the other for confirmation that a payment landed."}),"\n",(0,s.jsx)(a.h3,{id:"off-the-main-path",children:"Off the main path"}),"\n",(0,s.jsx)(a.p,{children:"Four more exchanges exist without belonging to a single admission."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Task."})," Where a Provider wants a rejected or partly paid claim looked at again, or wants an approved preauthorisation cancelled, it does not reopen the original exchange. It raises a ",(0,s.jsx)(a.strong,{children:"Task"}),", a general-purpose request that names the case it concerns and what is being asked of it, answered by the Payer through the corresponding callback. Reprocess, cancel and arbitration are all carried this way, which is why one exchange covers what look like three unrelated actions."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Search."})," Providers and regulatory bodies can look up claim information, which is a read rather than part of any claim's progress."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"ABHA linking."})," A Payer links an ABHA number to a policy when the policy is created, and can de-link it later. This is what makes the beneficiary findable by ABHA at the point of care, and it is covered in the next chapter."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Predetermination."})," Before treatment is planned in detail, a hospital can ask the payer what it would pay for a proposed course of treatment. The payer answers from the policy and the beneficiary's history. It uses the same shape as a preauthorisation but commits nobody to anything."]}),"\n",(0,s.jsxs)(a.p,{children:["One stage of the journey has no exchange of its own. ",(0,s.jsx)(a.em,{children:"Intimation"})," is absorbed into the eligibility and preauthorisation exchanges rather than carried separately."]}),"\n",(0,s.jsx)(a.h2,{id:"what-a-participant-must-build",children:"What a participant must build"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"A Provider application"})," calls the exchange for eligibility, preauthorisation, claim submission, search, reprocessing and cancellation, and hosts callbacks for the Payer's communication requests and payment notices."]}),"\n",(0,s.jsxs)(a.li,{children:[(0,s.jsx)(a.strong,{children:"A Payer application"})," hosts callbacks for eligibility, plan details, preauthorisation and claim submissions, and calls the exchange to raise communication requests, send payment notices and manage ABHA-to-policy links."]}),"\n"]}),"\n",(0,s.jsx)(a.p,{children:"Both implement the shared use cases."}),"\n",(0,s.jsx)(a.h2,{id:"where-the-detail-lives",children:"Where the detail lives"}),"\n",(0,s.jsx)(a.p,{children:"Three chapters follow, and they divide the work between them."}),"\n",(0,s.jsx)(a.p,{children:"The next chapter, Participants and Policies, covers the groundwork every exchange depends on. How a participant joins the network and is found on it, how a session is obtained, how keys are made and fetched, and how a beneficiary is matched to a policy. None of it is a claim exchange, and all of it has to be in place before one can be attempted."}),"\n",(0,s.jsx)(a.p,{children:"JWE, Status and Errors then describes the message itself. The envelope and the sealed letter inside it, every field on the envelope, the status words, what the exchange's receipt looks like, and what happens when something is refused."}),"\n",(0,s.jsx)(a.p,{children:"The NHCX Use Cases chapter then takes each exchange named here and gives its endpoints. The action endpoint the initiator calls, the callback the responder implements, and the workflow code that tells one transaction from another where several share an endpoint. The codes themselves are collected in the Workflow Codes chapter that follows it. The exchanges are grouped there by who drives them: shared by both sides, driven by the Provider, or driven by the Payer. That grouping tells an integrator which half of each exchange it has to build."})]})}function d(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}}}]);